mapper.select:
SELECT wb.total_words,
       COALESCE(ubs.daily_goal, u.daily_goal) AS daily_goal,
       (
           SELECT COUNT(*)
           FROM user_word_progress p
           JOIN words w ON w.id = p.word_id
           WHERE p.user_id = #{userId} AND w.book_id = #{bookId}
       ) AS learned_words,
       (
           SELECT COUNT(*)
           FROM user_word_progress p
           JOIN words w ON w.id = p.word_id
           WHERE p.user_id = #{userId}
             AND w.book_id = #{bookId}
             AND p.status = 'MASTERED'
       ) AS mastered_words,
       (
           SELECT COUNT(*)
           FROM user_word_progress p
           JOIN words w ON w.id = p.word_id
           WHERE p.user_id = #{userId}
             AND w.book_id = #{bookId}
             AND p.next_review_at <= #{now}
             AND p.status <> 'MASTERED'
       ) AS due_words,
       (
           SELECT COUNT(DISTINCT r.word_id)
           FROM review_logs r
           JOIN words w ON w.id = r.word_id
           WHERE r.user_id = #{userId}
             AND w.book_id = #{bookId}
             AND r.reviewed_at >= #{dayStart}
             AND r.reviewed_at < #{dayEnd}
       ) AS today_reviewed
FROM word_books wb
JOIN users u ON u.id = #{userId}
LEFT JOIN user_book_settings ubs
    ON ubs.user_id = u.id AND ubs.book_id = wb.id
WHERE wb.id = #{bookId}

SELECT r.reviewed_at
FROM review_logs r
WHERE r.user_id = #{userId}
  AND r.reviewed_at < #{before}
ORDER BY r.reviewed_at DESC
